import { describe, expect, test } from "bun:test";
import { BUNDLED_CONNECTORS } from "@musepi/pi-coding-agent/connectors/bundled-catalog";
import { CONNECTOR_BRAND_GLYPHS } from "../src/components/settings-sections/connector-brand-icons.generated";

/**
 * The brand marks are committed data, generated by
 * `scripts/generate-connector-brand-icons.ts`. Nothing at runtime proves they
 * still cover the catalog, so this pins the contract instead: a connector
 * added without regenerating shows up here rather than as a bare initial in
 * the settings page.
 */

/**
 * Brands with no mark anywhere.
 *
 * DeepWiki's site declares its icon as the empty data URI, so there is nothing
 * to take. Every other entry must have a mark; adding an id here means the
 * card shows the name's first character.
 */
const NO_MARK = new Set(["deepwiki"]);

describe("connector brand marks", () => {
	test("every bundled connector has a mark or is a known exception", () => {
		const covered = BUNDLED_CONNECTORS.filter(entry => CONNECTOR_BRAND_GLYPHS[String(entry.id)] !== undefined);
		const missing = BUNDLED_CONNECTORS.map(entry => String(entry.id))
			.filter(id => CONNECTOR_BRAND_GLYPHS[id] === undefined && !NO_MARK.has(id))
			.sort();

		expect(missing).toEqual([]);
		expect(covered.length + NO_MARK.size).toBeGreaterThanOrEqual(BUNDLED_CONNECTORS.length);
	});

	test("no mark belongs to a connector that no longer exists", () => {
		const ids = new Set(BUNDLED_CONNECTORS.map(entry => String(entry.id)));
		expect(Object.keys(CONNECTOR_BRAND_GLYPHS).filter(id => !ids.has(id))).toEqual([]);
	});

	test("each mark is a usable vector or an image data URI", () => {
		for (const [id, glyph] of Object.entries(CONNECTOR_BRAND_GLYPHS)) {
			if ("src" in glyph) {
				expect(glyph.src.startsWith("data:image/"), `${id} has a non-image data URI`).toBe(true);
				continue;
			}
			expect(glyph.viewBox.length, `${id} has no viewBox`).toBeGreaterThan(0);
			expect(glyph.paths.length, `${id} has no path`).toBeGreaterThan(0);
			for (const path of glyph.paths) {
				expect(/^[Mm]/.test(path.d), `${id} has a path that does not start with a move`).toBe(true);
			}
		}
	});
});
